#!/usr/bin/env python3
"""
Independent DPLL SAT verifier v3 - optimized backtracking.

Uses proper backtracking (undo assignments on backtrack) instead of copy-on-branch,
while maintaining correctness. Unit propagation and pure literal elimination.

agent-0172 · stdlib only
"""

import argparse
import hashlib
import json
import os
import sys
import time

def dpll_sat(n_vars, clauses, max_time=None):
    """
    DPLL SAT solver with proper backtracking.
    Returns True (SAT), False (UNSAT), or None (timeout).
    """
    start_time = time.time()

    # Convert to sets for faster manipulation
    cls = [set(c) for c in clauses]
    assign = {}  # var -> bool

    # Stack for backtracking: list of (var, value, was_unit_propagated)
    trail = []

    def push_assignment(v, val):
        assign[v] = val
        trail.append(v)

    def pop_assignment():
        if trail:
            v = trail.pop()
            del assign[v]
            return v
        return None

    def unit_propagate():
        """Returns True if OK, False if conflict."""
        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(cls):
                c = cls[i]
                new_c = set()
                sat = False
                for lit in c:
                    v = abs(lit)
                    if v in assign:
                        if (lit > 0 and assign[v]) or (lit < 0 and not assign[v]):
                            sat = True
                            break
                    else:
                        new_c.add(lit)
                if sat:
                    cls.pop(i)
                    continue
                cls[i] = new_c
                if len(new_c) == 0:
                    return False
                if len(new_c) == 1:
                    lit = next(iter(new_c))
                    v = abs(lit)
                    val = lit > 0
                    if v not in assign:
                        push_assignment(v, val)
                        changed = True
                        cls.pop(i)
                        continue
                    else:
                        if assign[v] != val:
                            return False
                i += 1
        return True

    def find_pure_literals():
        """Returns list of (var, value) pure literals."""
        pos = set()
        neg = set()
        for c in cls:
            for lit in c:
                v = abs(lit)
                if v not in assign:
                    if lit > 0:
                        pos.add(v)
                    else:
                        neg.add(v)
        pure = []
        for v in pos - neg:
            pure.append((v, True))
        for v in neg - pos:
            pure.append((v, False))
        return pure

    def apply_pure_literals(pure):
        """Apply pure literal assignments. Returns number applied."""
        count = 0
        for v, val in pure:
            if v not in assign:
                push_assignment(v, val)
                count += 1
        if count == 0:
            return 0
        # Remove satisfied clauses
        new_cls = []
        for c in cls:
            sat = False
            new_c = set()
            for lit in c:
                v = abs(lit)
                if v in assign:
                    if (lit > 0 and assign[v]) or (lit < 0 and not assign[v]):
                        sat = True
                        break
                else:
                    new_c.add(lit)
            if not sat:
                new_cls.append(new_c)
        cls[:] = new_cls
        return count

    def choose_variable():
        for c in cls:
            for lit in c:
                v = abs(lit)
                if v not in assign:
                    return v
        return None

    def solve():
        if max_time and time.time() - start_time > max_time:
            return None

        # Save state for backtracking
        trail_start = len(trail)
        cls_snapshot = [set(c) for c in cls]

        # Unit propagation
        if not unit_propagate():
            # Conflict - backtrack
            _backtrack(trail_start, cls_snapshot)
            return False

        # Pure literal elimination
        while True:
            pure = find_pure_literals()
            if not pure:
                break
            apply_pure_literals(pure)
            if not unit_propagate():
                _backtrack(trail_start, cls_snapshot)
                return False

        # Check if all satisfied
        if not cls:
            _backtrack(trail_start, cls_snapshot)
            return True

        if max_time and time.time() - start_time > max_time:
            _backtrack(trail_start, cls_snapshot)
            return None

        # Choose variable
        v = choose_variable()
        if v is None:
            _backtrack(trail_start, cls_snapshot)
            return True

        # Try True
        push_assignment(v, True)
        result = solve()
        if result is True:
            # Don't backtrack - keep the assignment (SAT found)
            return True
        if result is None:
            _backtrack(trail_start, cls_snapshot)
            return None
        # Backtrack from True branch
        # (already partially backtracked by the recursive call)
        # Make sure we're back to trail_start
        while len(trail) > trail_start:
            pop_assignment()
        cls[:] = [set(c) for c in cls_snapshot]

        if max_time and time.time() - start_time > max_time:
            return None

        # Try False
        push_assignment(v, False)
        result = solve()
        if result is True:
            return True
        if result is None:
            _backtrack(trail_start, cls_snapshot)
            return None

        # Both branches failed - UNSAT
        _backtrack(trail_start, cls_snapshot)
        return False

    def _backtrack(trail_start, cls_snapshot):
        """Restore state to trail_start."""
        while len(trail) > trail_start:
            pop_assignment()
        cls[:] = [set(c) for c in cls_snapshot]

    return solve()


def parse_dimacs(filepath):
    n_vars = 0
    clauses = []
    current = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('c'):
                continue
            if line.startswith('p'):
                n_vars = int(line.split()[2])
                continue
            for tok in line.split():
                lit = int(tok)
                if lit == 0:
                    if current:
                        clauses.append(current)
                    current = []
                else:
                    current.append(lit)
    if current:
        clauses.append(current)
    return n_vars, clauses


def file_sha256(filepath):
    with open(filepath, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()


def run_selftest():
    results = []
    def check(name, cond, note=""):
        results.append((name, bool(cond), note))
        print(f"  [{'PASS' if cond else 'FAIL'}] {name} {f'({note})' if note else ''}", flush=True)

    check("T1 empty formula SAT", dpll_sat(1, []) is True)
    check("T2 empty clause UNSAT", dpll_sat(1, [[]]) is False)
    check("T3 unit clause SAT", dpll_sat(1, [[1]]) is True)
    check("T4 contradictory units UNSAT", dpll_sat(1, [[1], [-1]]) is False)
    check("T5 simple 2-SAT SAT", dpll_sat(2, [[1,2],[-1,2],[1,-2]]) is True)
    check("T6 unsatisfiable 2-SAT UNSAT", dpll_sat(2, [[1,2],[1,-2],[-1,2],[-1,-2]]) is False)

    def php(p, h):
        cls = []
        def var(i,j): return i*h+j+1
        for i in range(p):
            cls.append([var(i,j) for j in range(h)])
        for j in range(h):
            for a in range(p):
                for b in range(a+1,p):
                    cls.append([-var(a,j), -var(b,j)])
        return p*h, cls

    nv, c = php(3,2)
    check("T7 PHP(3,2) UNSAT", dpll_sat(nv, c) is False)
    nv, c = php(4,3)
    check("T8 PHP(4,3) UNSAT", dpll_sat(nv, c) is False)
    nv, c = php(3,4)
    check("T9 PHP(3,4) SAT", dpll_sat(nv, c) is True)

    # DIMACS parser test
    tp = "/tmp/test_v3.cnf"
    with open(tp, 'w') as f:
        f.write("c t\np cnf 3 2\n1 2 0\n-1 -2 3 0\n")
    nv, c = parse_dimacs(tp)
    check("T10 DIMACS parser", nv == 3 and len(c) == 2)
    os.unlink(tp)

    passed = sum(1 for _, ok, _ in results if ok)
    total = len(results)
    print(f"\nSelftest: {passed}/{total} passed", flush=True)
    return passed, total


def main():
    ap = argparse.ArgumentParser(description="DPLL SAT verifier v3 (agent-0172)")
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--verify", type=str, metavar="FILE")
    ap.add_argument("--time-limit", type=float, default=None)
    ap.add_argument("--output", type=str, default=None)
    ap.add_argument("-v", "--verbose", action="store_true")
    args = ap.parse_args()

    output = {"tool": os.path.basename(__file__), "agent": "agent-0172", "version": "v3"}

    if args.selftest:
        p, t = run_selftest()
        output["selftest"] = f"{p}/{t}"
        if p != t:
            sys.exit(1)

    if args.verify:
        if args.verbose:
            print(f"Verifying: {args.verify}", flush=True)
        sha = file_sha256(args.verify)
        nv, clauses = parse_dimacs(args.verify)
        if args.verbose:
            print(f"  SHA-256: {sha[:16]}...")
            print(f"  Variables: {nv}, Clauses: {len(clauses)}")

        t0 = time.time()
        result = dpll_sat(nv, clauses, max_time=args.time_limit)
        elapsed = time.time() - t0
        verdict = "SAT" if result else ("UNSAT" if result is False else "TIMEOUT")

        if args.verbose:
            print(f"  Verdict: {verdict}")
            print(f"  Time: {elapsed:.2f}s")

        output["verify"] = {
            "file": args.verify, "sha256": sha,
            "n_vars": nv, "n_clauses": len(clauses),
            "verdict": verdict, "time_seconds": round(elapsed, 3)
        }

    if args.output:
        with open(args.output, "w") as f:
            json.dump(output, f, indent=2)
        if args.verbose:
            print(f"\nWrote {args.output}")


if __name__ == "__main__":
    main()

